package thaumcraft.verification;
import net.minecraft.core.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.phys.*;
import thaumcraft.registry.*;import thaumcraft.entities.*;import thaumcraft.production.*;import thaumcraft.items.*;import thaumcraft.api.aspects.*;
final class MechanicsReviewScene {
 static CrucibleBlockEntity crucible;static ItemStack charging;static thaumcraft.blocks.AuraNodeBlockEntity consumer,victim;static int consumed;static boolean tentacleSpawned;
 static void prepare(int scene){var p=PhotoLiveScene.player;var l=p.serverLevel();var o=PhotoLiveScene.O;crucible=null;
  if(scene==92){l.setBlockAndUpdate(o,R3Content.ENERGIZED_NODE.get().defaultBlockState());l.setBlockAndUpdate(o.west(3),R2Content.ARCANE_WORKBENCH.get().defaultBlockState());l.setBlockAndUpdate(o.west(3).above(),R3Content.WORKBENCH_CHARGER.get().defaultBlockState());charging=PhotoLiveScene.wand();for(var a:Aspects.PRIMALS)WandVis.set(charging,a,0);((thaumcraft.blocks.TableBlockEntity)l.getBlockEntity(o.west(3))).setItem(10,charging);p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(R2Content.GOGGLES.get()));}
  if(scene>=93&&scene<=95||scene>=103&&scene<=107||scene==112||scene==113){l.setBlockAndUpdate(o,R3Content.CRUCIBLE.get().defaultBlockState());crucible=(CrucibleBlockEntity)l.getBlockEntity(o);int water=scene==113?0:scene==103?250:scene==104||scene==105?500:1000;crucible.fillWater(water);crucible.heat=scene==93?0:scene==112?150:200;if(scene>=105&&scene!=113||scene==94||scene==95)crucible.store.addToContainer(Aspects.AIR,scene==107?110:scene==106?100:20);crucible.sync();if(scene>=103)p.teleportTo(.5,66,2.8);p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(R2Content.GOGGLES.get()));p.setItemInHand(InteractionHand.MAIN_HAND,PhotoLiveScene.wand());}
  if(scene==96){l.setBlockAndUpdate(o,R3Content.FOCAL_MANIPULATOR.get().defaultBlockState());var tile=(FocalManipulatorBlockEntity)l.getBlockEntity(o);tile.setItem(0,new ItemStack(R3Equipment.FOCI.get("trade").get()));}
  if(scene==97){for(int x=-4;x<=4;x++)for(int z=-4;z<=2;z++){var at=o.offset(x,0,z);if(x<0&&z<0)l.setBlockAndUpdate(at.below(),R2Content.TAINTED_SOIL.get().defaultBlockState());thaumcraft.blocks.TaintFibresBlock.spread(l,at);}for(int y=0;y<3;y++)for(int x=-2;x<=2;x++)l.setBlockAndUpdate(o.offset(x,y,-3),Blocks.STONE.defaultBlockState());for(int x=-2;x<=2;x++)for(int y=0;y<3;y++)thaumcraft.blocks.TaintFibresBlock.spread(l,o.offset(x,y,-2));p.teleportTo(4.5,67,6.5);}
  if(scene==98){tentacleSpawned=false;l.setDayTime(18000);for(int x=24;x<=72;x++)for(int z=-24;z<=24;z++){l.setBlock(new BlockPos(x,64,z),Blocks.STONE.defaultBlockState(),2);l.setBlock(new BlockPos(x,65,z),R2Content.TAINT_FIBRES.get().defaultBlockState().setValue(MultifaceBlock.getFaceProperty(Direction.DOWN),true),2);l.setBlock(new BlockPos(x,71,z),Blocks.STONE.defaultBlockState(),2);thaumcraft.world.WorldBiomes.change(l,x,z,thaumcraft.world.WorldBiomes.TAINT);}p.setGameMode(GameType.SURVIVAL);}
  if(scene==99){p.getInventory().setItem(8,new ItemStack(R2Content.TAINT_GOO.get(),64));p.removeEffect(thaumcraft.effects.TaintEffects.FLUX_TAINT);}
  if(scene==100||scene==114){p.removeAllEffects();p.setHealth(p.getMaxHealth());l.getGameRules().getRule(GameRules.RULE_KEEPINVENTORY).set(false,p.server);p.setGameMode(GameType.SURVIVAL);var helmet=new ItemStack(R3Equipment.ARMOR.get("thaumium_helmet").get());for(int i=0;i<8;i++)thaumcraft.equipment.RunicShield.harden(helmet);p.setItemSlot(EquipmentSlot.HEAD,helmet);p.getInventory().setItem(8,PhotoLiveScene.wand());}
  if(scene==101||scene==102||scene==111){var leader=R5Entities.CULTIST_LEADER.get().create(l);leader.moveTo(.5,65,.5,scene==101?35:-145,0);leader.finalizeSpawn(l,l.getCurrentDifficultyAt(o),MobSpawnType.COMMAND,null);leader.setNoAi(true);leader.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R5Content.CRIMSON_SWORD.get()));leader.yBodyRot=leader.yHeadRot=leader.getYRot();l.addFreshEntity(leader);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R5Content.CRIMSON_SWORD.get()));p.teleportTo(2.5,65,4.5);}
  if(scene==108){FollowupReviewScene.node(o.west());FollowupReviewScene.node(o.east());consumer=(thaumcraft.blocks.AuraNodeBlockEntity)l.getBlockEntity(o.west());victim=(thaumcraft.blocks.AuraNodeBlockEntity)l.getBlockEntity(o.east());consumer.initialize(java.util.Map.of("aer",100),thaumcraft.api.nodes.NodeState.Type.NORMAL,thaumcraft.api.nodes.NodeState.Modifier.NONE);victim.initialize(java.util.Map.of("aer",50),thaumcraft.api.nodes.NodeState.Type.NORMAL,thaumcraft.api.nodes.NodeState.Modifier.NONE);p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(R2Content.GOGGLES.get()));consumed=0;}
 }
 static void tick(int scene,int age)throws Exception {var p=PhotoLiveScene.player;var l=p.serverLevel();var o=PhotoLiveScene.O;
  if(crucible!=null){crucible.heat=scene==93?0:scene==112?150:200;if(scene==107&&age%10==0){crucible.store.clear();crucible.store.addToContainer(Aspects.AIR,110);l.setBlockAndUpdate(o.above(),Blocks.AIR.defaultBlockState());}if(age%10==0)crucible.sync();}
  if(scene==96&&age==20){var tile=(FocalManipulatorBlockEntity)l.getBlockEntity(o);p.openMenu(new SimpleMenuProvider((id,inv,owner)->new thaumcraft.menu.FocalManipulatorMenu(id,inv,tile),net.minecraft.network.chat.Component.literal("Focal Manipulator")),b->b.writeBlockPos(o));}
  if(scene==92&&age==60)PhotoLiveScene.check(WandVis.get(charging,Aspects.AIR)>0,"real workbench charger consumes vis from energized node while aspects remain available");
  if(scene==95&&age==40){p.setShiftKeyDown(true);var hit=new BlockHitResult(o.getCenter(),Direction.UP,o,false);var result=p.gameMode.useItemOn(p,l,p.getMainHandItem(),InteractionHand.MAIN_HAND,hit);p.setShiftKeyDown(false);PhotoLiveScene.check(result.consumesAction()&&crucible.water()==0&&crucible.store.amount()==0,"actual server useItemOn sneaking wand empties crucible water and aspects");}
  if(scene==98&&age>=20&&age<=65&&!tentacleSpawned){for(int i=0;i<8;i++)NaturalSpawner.spawnCategoryForPosition(MobCategory.MONSTER,l,new BlockPos(48,65,0));var found=l.getEntitiesOfClass(Taintacle.class,new AABB(24,64,-24,73,71,25));if(!found.isEmpty()){tentacleSpawned=true;found.forEach(e->e.setNoAi(true));p.teleportTo(48.5,65,8.5);}}
  if(scene==98&&age==70)PhotoLiveScene.check(tentacleSpawned,"native NaturalSpawner chooses and spawns a taintacle on dark taint fibres in tainted biome");
  if(scene==99&&age==30){long seed=0;for(;;seed++){var r=net.minecraft.util.RandomSource.create(seed);if(r.nextInt(4321)<=64)break;}l.random.setSeed(seed);p.getInventory().tick();PhotoLiveScene.check(p.hasEffect(thaumcraft.effects.TaintEffects.FLUX_TAINT)&&p.getInventory().getItem(8).getCount()==63,"actual inventory update consumes unstable tainted goo and applies original poison");for(int i=0;i<32;i++){var slime=R2Entities.THAUMIC_SLIME.get().create(l);slime.size(1);slime.setNoAi(true);slime.moveTo(.5,65,.5);l.addFreshEntity(slime);slime.hurt(l.damageSources().playerAttack(p),1000);}PhotoLiveScene.check(l.getEntitiesOfClass(ItemEntity.class,new AABB(o).inflate(4)).stream().anyMatch(e->e.getItem().is(R2Content.TAINT_GOO.get())),"actual small thaumic slime deaths drop tainted goo");}
  if(scene==114&&age==32){PhotoLiveScene.check(thaumcraft.equipment.RunicShield.charge(p)>0,"runic armor is charged before removing it alive");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);}
  if(scene==114&&age==60)PhotoLiveScene.check(thaumcraft.equipment.RunicShield.charge(p)==0,"removing runic gear alive clears server shield immediately");
  if(scene==100&&age==32){PhotoLiveScene.check(thaumcraft.equipment.RunicShield.charge(p)>0,"runic shield is actually charged before death");p.hurt(l.damageSources().fellOutOfWorld(),1000);PhotoLiveScene.check(!p.isAlive()&&thaumcraft.equipment.RunicShield.charge(p)==0,"actual player death immediately clears server runic state");}
  if(scene==100&&age==75)PhotoLiveScene.check(p.isAlive()&&p.getItemBySlot(EquipmentSlot.HEAD).isEmpty()&&thaumcraft.equipment.RunicShield.charge(p)==0,"respawn without lost runic armor retains no stale shield");
  if(scene==108&&age>=25&&age<=60&&age%5==0){consumer.state.ticks=2;var method=thaumcraft.world.NodeEffects.class.getDeclaredMethod("exchange",thaumcraft.blocks.AuraNodeBlockEntity.class,ServerLevel.class,java.util.Random.class);method.setAccessible(true);long seed=0;for(;;seed++){var r=new java.util.Random(seed);if(r.nextInt(5)-r.nextInt(5)==2&&r.nextInt(5)-r.nextInt(5)==0&&r.nextInt(5)-r.nextInt(5)==0)break;}if((Boolean)method.invoke(null,consumer,l,new java.util.Random(seed)))consumed++;}
  if(scene==108&&age==70)PhotoLiveScene.check(consumed>=4,"actual node bullying transfer emits network effects repeatedly");
 }
}
